package com.example.jobfinderapp.activities;import android.os.*;import android.widget.*;import androidx.appcompat.app.*;import com.example.jobfinderapp.R;import com.example.jobfinderapp.database.DBHelper;import com.example.jobfinderapp.models.Job;import com.example.jobfinderapp.models.User;import com.example.jobfinderapp.utils.UserSession;public class AdminJobDetailActivity extends AppCompatActivity{DBHelper db;int id;TextView info;public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_admin_job_detail);db=DBHelper.getInstance(this);UserSession s=new UserSession(this);User u=db.getUserById(s.getUserId());if(u==null||!DBHelper.ROLE_ADMIN.equals(u.getRole())||!DBHelper.STATUS_ACTIVE.equals(u.getStatus())){finish();return;}id=getIntent().getIntExtra("JOB_ID",-1);info=findViewById(R.id.tvAdminJobDetail);findViewById(R.id.btnHideJob).setOnClickListener(v->change("Bị ẩn"));findViewById(R.id.btnCloseJob).setOnClickListener(v->change("Đã đóng"));findViewById(R.id.btnOpenJob).setOnClickListener(v->change("Đang tuyển"));load();}void load(){Job j=db.getJobById(id);if(j==null){finish();return;}info.setText(j.getTitle()+"\n"+j.getCompanyName()+"\n"+j.getLocation()+"\n"+j.getSalary()+"\nTrạng thái: "+j.getStatus()+"\n\n"+j.getDescription()+"\n\nYêu cầu: "+j.getRequirement());}void change(String s){if(db.updateJobStatusByAdmin(id,s))load();}}
